pid_t pgid;
pid_t target_pid = 1; // Example: Init process PGID

// Get PGID of calling process (pid = 0)
pgid = getpgid(0);

// Get PGID of specified process
pgid = getpgid(target_pid);

// Check for failure
if (pgid == -1) {
    // errno set upon failure
    // Common error: ESRCH (Process not found)
    int err = errno;
    // ... handle error
}

// Related: Equivalent to getpgid(0)
pid_t self_pgid = getpgrp();

